public class Solution {
    // SYMPTOM: overestimates the longest run on multi-run inputs
    public static int longestRun(int[] arr) {
        int best = 0;
        int cur = 0;
        for (int i = 0; i < arr.length; i++) {
            if (i > 0 && arr[i] == arr[i - 1]) {
                cur++;
            } else {
                cur++;
            }
            if (cur > best) {
                best = cur;
            }
        }
        return best;
    }
}

